 private static Scope scope(){var list=scopes.get();return overflow.get()!=null||list==null?null:list.peekLast();}
 private static IsoPlayer local(){return IsoPlayer.players.length==0?null:IsoPlayer.players[0];}
 static boolean alias(String name){if(name==null)return false;for(var group:new String[]{"01","02"}){String prefix="fixtures_windows_curtains_"+group+"_";if(name.startsWith(prefix)){String n=name.substring(prefix.length());try{int value=Integer.parseInt(n);return n.equals(Integer.toString(value))&&value>=0&&value<(group.equals("01")?96:32);}catch(NumberFormatException invalid){return false;}}}return false;}
 private static Path ownershipRoot(PackBind b){if(b==null||b.model==null||b.model.obj==null)return null;var path=b.model.obj.toPath().toAbsolutePath().normalize();var parent=path.getParent();return parent!=null&&parent.getFileName()!=null&&parent.getFileName().toString().equals("dgv_curtains")?parent:null;}
 private static Path root(PackBind b,IsoSprite sprite){var parent=ownershipRoot(b);return parent!=null&&sprite!=null&&alias(sprite.name)&&b.model.obj.getName().equals(sprite.name+".obj")?parent:null;}
 /** Selected renderer ownership is independent of successful physical admission, including Off. */
 public static boolean owns(IsoObject o){if(o==null||!o.getClass().getName().equals("zombie.iso.objects.IsoCurtain"))return false;try{return o.getClass()==IsoCurtain.class&&o.getSprite()!=null&&ownershipRoot(ModelPacks.bind(o.getSprite()))!=null;}catch(RuntimeException|LinkageError unavailable){return false;}}
 private static boolean nearOwner(IsoObject owner,int distance){var p=local();var here=p==null?null:p.getSquare();var square=owner==null?null:owner.getSquare();return here!=null&&square!=null&&p.getCell()!=null&&square.getZ()==here.getZ()&&Math.abs(square.getX()-here.getX())<=distance&&Math.abs(square.getY()-here.getY())<=distance&&p.getCell().getGridSquare(square.getX(),square.getY(),square.getZ())==square;}
 private static boolean context(IsoPlayer p,boolean rig){if(!enabled)return false;try{long now=System.nanoTime();var input=Engine.latestInput;var frame=WorldRigCapture.latest;return enabled&&Main.ready()&&p!=null&&p==local()&&!p.isDead()&&p.getVehicle()==null&&p.getCell()!=null&&p.getSquare()!=null&&Engine.active()&&Engine.worldPresent&&input!=null&&input.focused()&&now>=input.time()&&now-input.time()<250_000_000L&&!zombie.network.GameClient.client&&!zombie.network.GameServer.server&&!zombie.GameTime.isGamePaused()&&!VrApi.fullHud()&&!VrApi.pointerActive()&&!zombie.ui.UIManager.isModalVisible()&&!zombie.core.Core.getInstance().isDoingTextEntry()&&(!rig||frame!=null&&frame.actor()==p&&frame.fresh(now)&&input.time()>=frame.inputTime()&&input.time()-frame.inputTime()<150_000_000L&&frame.scene() instanceof SceneData);}catch(RuntimeException|LinkageError unavailable){return false;}}
 private static boolean validPose(Scope s){return s.square!=null&&s.actor!=null&&s.binding!=null&&s.slot==(s.square.getX()&7)+(s.square.getY()&7)*8&&Float.isFinite(s.x)&&Float.isFinite(s.y)&&Float.isFinite(s.h)&&Math.abs(s.x-((s.square.getX()&7)+.5f))<.0001&&Math.abs(s.y-((s.square.getY()&7)+.5f))<.0001&&Math.abs(s.h-(s.square.getZ()*Math.sqrt(6)+s.rise))<.0001;}
 private static boolean unchanged(Scope s){return s.owner!=null&&enabled&&Thread.currentThread()==ownerThread&&s.epoch==epoch&&context(s.actor,false)&&nearOwner(s.owner,1)&&s.actor==actor.get()&&s.actor.getCell()==cell.get()&&s.generation==ModelPacks.generation()&&s.owner.getSquare()==s.square&&s.actor.getCell().getGridSquare(s.square.getX(),s.square.getY(),s.square.getZ())==s.square&&s.owner.getObjectIndex()>=0&&s.owner.getObjectIndex()<s.square.getObjects().size()&&s.square.getObjects().get(s.owner.getObjectIndex())==s.owner&&s.owner.getSprite()==s.sprite&&s.owner.IsOpen()==s.open&&s.owner.getNorth()==s.north&&s.owner.getObjectAttachedTo()==s.attached&&WorldMesher.rise(s.owner)==s.rise&&ModelPacks.bind(s.sprite)==s.binding&&source!=null&&source.root.equals(root(s.binding,s.sprite))&&owns(s.owner);}
