 public static boolean enabled(){return enabled;}public static String status(){var s=source;return s!=null&&!s.verified?(s.failed?"Pack curtain provider source verification rejected; native rendering retained":"Pack curtain provider source verification pending; native rendering retained"):detail;}
 private static void remove(IsoCurtain o,long expected){synchronized(LOCK){var p=packets.get(o);if(p!=null&&p.epoch==expected)packets.remove(o);}}
 /** One discovery can request at most eight native recooks, with a separate 250 ms retry per owner. */
