 private static boolean ensureSource(Path root,int generation){if(root==null)return false;Source job;synchronized(LOCK){var old=source;if(old!=null&&old.generation==generation)return old.root.equals(root);epoch++;packets.clear();job=new Source(root,generation,epoch,false,false);source=job;}verifier.execute(()->verify(job));return true;}
 private static void verify(Source job){try{long total=0;for(String line:PackCurtainAssets.HASHES.split("\n")){if(Thread.currentThread().isInterrupted()||!enabled||source!=job)return;var parts=line.split(" ");if(parts.length!=2)throw new IllegalArgumentException("Curtain source inventory");Path file=job.root.resolve(parts[0]).normalize();if(!file.getParent().equals(job.root)||!file.toRealPath().equals(file))return;var before=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!before.isRegularFile()||before.size()<1||before.size()>4*1024*1024||(total+=before.size())>16*1024*1024)return;var digest=MessageDigest.getInstance("SHA-256");try(var input=Files.newInputStream(file,LinkOption.NOFOLLOW_LINKS)){byte[] bytes=new byte[32768];int count;long read=0;while((count=input.read(bytes))!=-1){if((read+=count)>before.size())return;digest.update(bytes,0,count);}if(read!=before.size())return;}var after=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!Objects.equals(before.fileKey(),after.fileKey())||before.size()!=after.size()||!before.lastModifiedTime().equals(after.lastModifiedTime())||!HexFormat.of().formatHex(digest.digest()).equals(parts[1]))return;}synchronized(LOCK){if(enabled&&source==job)source=new Source(job.root,job.generation,job.epoch,true,false);}}catch(Exception|LinkageError invalid){/* An unverified provider keeps original rendering and has no optional action or contact. */}finally{synchronized(LOCK){if(enabled&&source==job)source=new Source(job.root,job.generation,job.epoch,false,true);}}}
 static void requestObject(IsoObject o){if(o instanceof IsoCurtain c)request(c);}
 static Packet packetObject(IsoObject o){return o instanceof IsoCurtain c?packet(c):null;}
 static Packet packet(IsoCurtain o){Packet p;synchronized(LOCK){p=packets.get(o);}if(p==null)return null;return current(p)?p:null;}
 private static boolean retained(Packet p){synchronized(LOCK){return p!=null&&p.owner.get()!=null&&packets.get(p.owner.get())==p;}}
 static boolean current(Packet p){if(!retained(p))return false;try{var o=p.owner.get();var square=p.square.get();var player=p.actor.get();var sprite=p.sprite.get();var b=p.binding.get();var checked=source;var rig=WorldRigCapture.latest;if(!context(player,true)||Thread.currentThread()!=ownerThread||checked==null||!checked.verified||checked.epoch!=p.epoch||checked.generation!=p.generation||p.generation!=ModelPacks.generation()||o==null||square==null||sprite==null||b==null||!nearOwner(o,2)||player!=actor.get()||player.getCell()!=p.cell.get()||player.getCell()!=cell.get()||player.getCell().getGridSquare(square.getX(),square.getY(),square.getZ())!=square||o.getSquare()!=square||o.getSprite()!=sprite||!Objects.equals(sprite.name,p.name)||o.getObjectIndex()!=p.index||p.index<0||p.index>=square.getObjects().size()||square.getObjects().get(p.index)!=o||o.IsOpen()!=p.open||o.getNorth()!=p.north||o.getObjectAttachedTo()!=p.attached.get()||p.attachedPresent&&p.attached.get()==null||WorldMesher.rise(o)!=p.rise||ModelPacks.bind(sprite)!=b||!checked.root.equals(root(b,sprite))||b.x!=p.x||b.y!=p.y||b.z!=p.z||b.cos!=p.cos||b.sin!=p.sin||b.scale!=p.scale||b.model.state()!=PackModel.RESIDENT||PackedModelGeometry.get(b.model)!=p.mesh)return false;var data=NativeOwnerVisibility.committed(p.recipe.get(),square);return data!=null&&NativeOwnerVisibility.contents((SceneData)rig.scene(),data,square);}catch(RuntimeException|LinkageError invalid){return false;}}
 private static void maintain(IsoPlayer p){if(ownerThread!=null&&Thread.currentThread()!=ownerThread)return;long now=System.nanoTime();if(now<nextContactDiscovery)return;discovery(p);nextContactDiscovery=now+200_000_000L;var here=p.getSquare();int scanned=0;for(int dx=-1;dx<=1;dx++)for(int dy=-1;dy<=1;dy++){var square=p.getCell().getGridSquare(here.getX()+dx,here.getY()+dy,here.getZ());if(square==null)continue;var objects=square.getObjects();for(int i=0;i<objects.size();i++){if(++scanned>256)return;if(objects.get(i) instanceof IsoCurtain curtain&&curtain.getSquare()==square&&curtain.getObjectIndex()>=0)request(curtain);}}}
